export const localDay=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
export const uid=()=>globalThis.crypto.randomUUID();
export const initial=()=>({version:1,name:'小朋友',avatar:'🧒',pin:null,habits:[{id:'read',name:'阅读 20 分钟',icon:'📖',category:'学习成长',points:5,note:'在书里，发现一个新世界'},{id:'homework',name:'独立完成作业',icon:'✏️',category:'学习成长',points:10,note:'认真思考，自己也可以做到'},{id:'bed',name:'整理自己的小床',icon:'🛏️',category:'家务劳动',points:3,note:'从一个整洁的早晨开始'},{id:'dishes',name:'饭后收拾餐桌',icon:'🍽️',category:'家务劳动',points:5,note:'我是家里的小帮手'},{id:'brush',name:'早晚认真刷牙',icon:'🪥',category:'生活习惯',points:3,note:'让每一颗牙齿都闪闪发光'},{id:'move',name:'运动 30 分钟',icon:'⚽',category:'生活习惯',points:5,note:'动一动，让身体充满能量'}],rewards:[{id:'ice',name:'一份冰淇淋',icon:'🍦',cost:20,note:'给努力的自己一点甜',type:'reward'},{id:'tv',name:'看电视 30 分钟',icon:'📺',cost:30,note:'享受喜欢的快乐时光',type:'reward'},{id:'cash',name:'我的零花钱',icon:'💰',cost:10,note:'1 积分 = 1 元，由家长支付',type:'cash'},{id:'outing',name:'周末公园野餐',icon:'🧺',cost:60,note:'一起收藏美好的家庭时光',type:'reward'}],ledger:[],checks:[],orders:[]});
export const balance=s=>s.ledger.reduce((n,x)=>n+x.amount,0);
export function addEntry(s,amount,title,kind,extra={}){if(!Number.isSafeInteger(amount)||amount===0||Math.abs(amount)>1000000)throw Error('请输入 1～1,000,000 之间的整数');if(balance(s)+amount<0)throw Error('积分不足，不能扣成负数');const entry={id:uid(),amount,title,kind,at:new Date().toISOString(),...extra};s.ledger.unshift(entry);return entry;}
export function checkHabit(s,id,day=localDay()){const h=s.habits.find(h=>h.id===id);if(!h)throw Error('习惯不存在');if(s.checks.some(c=>c.habitId===id&&c.day===day))throw Error('今天已经打卡啦');const e=addEntry(s,h.points,h.name,'habit',{day});s.checks.push({habitId:id,day,entryId:e.id,name:h.name});return h.points;}
export function redeem(s,id,cashAmount){const r=s.rewards.find(r=>r.id===id);if(!r)throw Error('奖励不存在');const cost=r.type==='cash'?cashAmount:r.cost;if(!Number.isSafeInteger(cost)||cost<1)throw Error('请输入正整数金额');const title=r.type==='cash'?`${r.name} · ¥${cost}`:r.name;const e=addEntry(s,-cost,title,'redeem');const order={id:uid(),rewardId:id,title,icon:r.icon,cost,type:r.type,at:e.at,status:'pending'};s.orders.unshift(order);return order;}
export function fulfill(s,id){const o=s.orders.find(o=>o.id===id);if(!o||o.status!=='pending')throw Error('该兑换已处理');o.status='fulfilled';o.fulfilledAt=new Date().toISOString();}
export function cancel(s,id){const o=s.orders.find(o=>o.id===id);if(!o||o.status!=='pending')throw Error('该兑换已处理');addEntry(s,o.cost,`退回：${o.title}`,'refund');o.status='cancelled';}
